          "summary": "LINK : https://oklahoma.gov/content/dam/ok/en/treasurer/documents/inside-the-office/request-for-proposals/OCIO%20FINAL%20RFP%207%2015%2026.pdf The Invest in Oklahoma Board for the Oklahoma Taxpayer Endowment Trust Fund is soliciting proposals from qualified firms to provide Outsourced Chief Investment Officer (OCIO) services for the Fund. The selected OCIO will be responsible for managing a newly established investment portfolio of approximately $200 million. The Fund is expected to receive additional deposits over the contract term, resulting in significant asset growth. Proposals must satisfy all minimum qualifications and requirements outlined in the official Request for Proposal (RFP). The Board reserves the right to negotiate contract terms and conditions and to reject any or all proposals if deemed to be in the best interest of the Fund. The RFP is available on the Oklahoma State Treasurer's website under Inside the Office – Request for Proposals."
