          "posted_at": "2026-07-01",
          "relevant_date": "2026-08-06",
          "attachment_url": "https://www.mass.gov/info-details/wellesley-retirement-board-request-for-proposal",
          "source_url": "https://www.swfi.com/v1/compass/6a4f5a80c2a251268ad14690",
          "swfi_url": "https://www.swfi.com/v1/compass/6a4f5a80c2a251268ad14690",
          "summary": "LINK : https://www.mass.gov/info-details/wellesley-retirement-board-request-for-proposal The Wellesley Contributory Retirement Board and the Town of Wellesley are seeking proposals from qualified firms to provide investment consulting services for both the Wellesley Contributory Retirement System and the Town’s Other Post-Employment Benefits (OPEB) Trust. The selected consultant will monitor the performance of the Pension Reserves Investment Management (PRIM) Board, or any successor investment manager, and provide quarterly performance reporting for all investment funds and total plan assets. Services will also include comprehensive asset allocation reporting using look-through analysis of multi-asset funds, annual capital market expectations for 10-, 20-, and 30-year periods, and regular reviews of the System’s investment policy and asset allocation strategy. Additional responsibilities include reviewing expected investment returns against actuarial assumptions, attending Retirement Board meetings at least semi-annually for performance and manager reviews, and providing ongoing investment education through periodic reports and publications. While separate contracts will ultimately be executed for the Retirement System and the Town’s OPEB Trust, the Town has expressed a preference to engage a single investment consultant to provide services to both entities. The Town's CFO/Finance Director, serving as an ex-officio member of the Retirement Board, will participate in the consultant selection process for both engagements."
