          "title": "Temasek Signals Major ReOrg by April 2026, Private Equity to Benefit",
          "name": "Temasek Signals Major ReOrg by April 2026, Private Equity to Benefit",
          "type": "Opportunity",
          "institution": "Temasek Holdings",
          "asset_class_or_strategy": "Private Equity Fund",
          "strategy": "Private Equity Fund",
