          "summary": "Massachusetts Housing Finance Agency Retirement System is looking to commit $30 million to an open-end core real estate fund. The pension fund has issued an RFP because of Massachusetts Public Employee Retirement Administration Commission requirements to put services up for bid every seven years. Current managers. AEW Capital Management and Intercontinental Real Estate can bid for the services. Massachusetts Housing Finance Agency Retirement System – Real Estate RFP The Board Members of the Massachusetts Housing Finance Agency Retirement System (hereinafter “the Board”) are seeking proposals from managers of open-end core real estate funds. The System intends to invest approximately $30 million. Only proposals for experienced managers of open-end core real estate funds will be considered. More specifically, the investment proposed should: (1) have a minimum net asset value of $1 billion and (2) be well diversified both geographically and by property type with greater than 30 properties. (3) be a constituent of the NCREIF ODCE Index. Secondary and fund-of-funds investments will not be considered. The objective of this Request for Proposal shall be to identify that manager whose expertise will best meet the System’s goals and needs. The funds shall be managed in compliance with Massachusetts General Laws, Chapter 32 and Chapter 176, the regulations of the Massachusetts Division of Public Employee Retirement Administration Commission, 840 CMR, and the Placement Agent Policy (available from https://www.mass.gov/lists/perac-compliance-investments-forms ). All materials submitted in connection with this search may be subject to disclosure consistent with Massachusetts Public Record laws. All bidders are hereby advised that any proposal selected shall be subject to (1) approval of the Board (2) a written contract and (3) approval of the engagement by the Massachusetts Public Employee Retirement Administration Commission (PERAC). Due date deadline: November 30th at 3:00 PM EST Link below for copy of RFP: https://app.diligencevault.com/#/login?redirectId=C5BE534E-8084-4F3A-814F-AC3509022AF4"
