          "summary": "LINK : https://dym-upload.saramin.co.kr/upload/dym2_5/332/3590/filedown/2025-08-04/03_nps_250804_01.pdf The job performance contents focus on the establishment and research of responsible investment strategies, particularly ESG integration, and supporting the development and implementation of a responsible investment plan. Responsibilities include supporting the drafting of agenda items for the Trustee Responsibility Committee, establishing and executing shareholder rights enforcement plans, and engaging in dialogue with companies on key management issues. The role involves supporting the exercise of voting rights for domestically and internationally held listed stocks, managing disclosures and publishing the annual report on responsible investment, and carrying out other tasks related to shareholder rights and responsible investment. The competency units include responsible investment, the exercise of shareholder rights, and research on corporate governance issues. These competencies are essential for ensuring that the fiduciary responsibility of the National Pension Service (NPS) aligns with global standards and sustainable investment practices. Required Skills & Knowledge Candidates are expected to possess strong knowledge of National Pension Fund-related regulations, capital markets, economic indicators, taxation, statistics, finance, and accounting. Additional skills include financial analysis, data collection and processing in relation to macroeconomics and financial markets, legal interpretation, negotiation, and effective communication. Analytical thinking, problem-solving, and professional ethics are crucial, along with an adaptable attitude that considers recent economic issues and evolving environments. Career Requirements Applicants must have at least three years of experience as a full-time investment manager and a minimum of one month of related job experience. Preferred Qualifications Preferred credentials include international and domestic certifications such as CFA (Level 1–3), CPA (Korea/USA/Other countries), Attorney (Korea/USA/Other countries), Actuary, Certified International Investment Analyst (CIIA), FRM, CAIA, Tax Accountant, Investment Asset Management Specialist, Financial Investment Analyst, and Asset Manager. These certifications enhance credibility and demonstrate advanced expertise in fiduciary and investment management."
