          "summary": "LINK : https://dym-upload.saramin.co.kr/upload/dym2_5/332/3590/filedown/2025-08-04/03_nps_250804_08.pdf The job performance contents focus on alternative risk management. Key responsibilities include pre-risk review of alternative investments (real estate, infrastructure, private equity, hedge funds, etc.), post-risk management of alternative investment portfolios and risk indicators, and fair value assessment of alternative investment assets. The role also covers derivatives risk management, performance evaluation, fund risk management, and compliance-related monitoring. Additional duties include developing performance benchmarks, conducting factor decomposition, and addressing legal and regulatory violations related to the National Pension Fund. The competency units include investment risk management, investment performance evaluation, fund risk management, and derivatives performance analysis, all of which ensure sound and compliant risk oversight of NPS’s alternative and derivatives portfolios. Required Skills & Knowledge Candidates must have knowledge of capital markets, portfolio management, risk management theory, performance evaluation methodologies, financial feasibility analysis, and data/system operations. Required skills include financial analysis, quantitative/statistical techniques, English communication (conversation, reading, writing), risk management system use, office software proficiency, and application of financial and legal frameworks. Career Requirements Applicants must have at least three years of full-time investment manager experience and at least one month of relevant job experience in alternative or derivatives risk management. Preferred Qualifications Preferred certifications include CFA (Level 1–3), CPA (Korea/USA/Other countries), Attorney (Korea/USA/Other countries), Actuary, Certified International Investment Analyst (CIIA), FRM (domestic/international), CAIA, Tax Accountant, Financial Investment Analyst, Investment Asset Management Specialist, and Asset Manager. These credentials provide advanced expertise in risk and performance management across complex alternative portfolios."
