          "source_url": "https://www.swfi.com/v1/compass/68a4c19271ae708eccd9bd02",
          "swfi_url": "https://www.swfi.com/v1/compass/68a4c19271ae708eccd9bd02",
          "summary": "LINK : https://dym-upload.saramin.co.kr/upload/dym2_5/332/3590/filedown/2025-08-04/03_nps_250804_09.pdf The job performance contents focus on legal affairs related to fund management. Responsibilities include reviewing laws and contracts for domestic and international fund management, providing legal advice and support to officers and employees, and overseeing litigation matters related to fund management. Additional duties include reviewing and managing legal risks for alternative investments, providing legal advice on voting rights exercise, selecting and managing external legal advisors, and managing disputes. The role also covers the drafting, review, and interpretation of contracts and legal documents, as well as advising on law amendments relevant to NPS fund management. The competency units include fund compliance, contract review, litigation management, and legal support, ensuring that NPS operates within a robust legal framework while managing its large-scale fund assets. Required Skills & Knowledge Candidates should possess knowledge of civil law, commercial law, capital markets, and financial investment practices. Required skills include the ability to interpret and apply laws and regulations, legal drafting and review, contract interpretation (including English contracts), negotiation, and situational awareness. Proficiency in office software and computer systems is also necessary, along with strong communication and persuasion skills. Career Requirements Applicants must have at least three years of combined investment and legal experience and at least one month of relevant employment experience. Preferred Qualifications A domestic lawyer license is required, while additional financial certifications (e.g., Investment Asset Management Specialist, Financial Investment Analyst, etc.) are optional but preferred. Strategic and creative thinking, problem-solving skills, and teamwork are considered valuable attributes."
