          "summary": "LINK: https://dym-upload.saramin.co.kr/upload/dym2_5/332/3590/filedown/2025-08-04/03_nps_250804_10.pdf The job performance contents focus on comprehensive fund management operations. Responsibilities include fund accounting, custody, registration, and settlement; preparation of financial statements and settlement reports; and the establishment of fund accounting policies. Duties also involve managing receipts/disbursements, stock and bond trustee banks, and foreign currency depository banks. The role covers tax support, including monitoring and responding to fund-related tax issues, risk reviews for alternative investments, and working with tax advisors. Additional tasks include securities lending, statistical data management, BTO infrastructure operation oversight, external audit response, and government reporting. The competency units include fund accounting, custody management, registration management, investment office management, and alternative investment asset management. These ensure transparency, compliance, and efficiency in NPS’s fund management processes. Required Skills & Knowledge Candidates should have knowledge of National Pension Fund regulations, capital markets, financial products, taxation, accounting, and international accounting standards. Skills required include office software use, statistical software, interpretation and application of financial laws, financial analysis, and careful data organization. Career Requirements Applicants must have either: Full-time Investment Manager with at least 3 years of investment experience and 1 month of recruitment experience, or Responsible Investment Manager with at least 7 years of investment experience and 1 year of recruitment experience. Preferred Qualifications Preferred certifications include CFA (Level 1–3), CPA (Korea/USA/Other countries), Attorney (Korea/USA/Other countries), Actuary, Certified International Investment Analyst (CIIA), FRM, CAIA, Tax Accountant, Investment Asset Management Specialist, Financial Investment Analyst, and Asset Manager. These credentials demonstrate advanced professional competence in global fund operations and compliance."
