          "summary": "LINK : https://dym-upload.saramin.co.kr/upload/dym2_5/332/3590/filedown/2025-08-04/03_nps_250804_11.pdf The job performance contents focus on fund information systems and IT-based fund management support. Responsibilities include fund information planning, operation, analysis, infrastructure, and intelligence. Tasks involve developing order management systems, investment strategy and performance systems, risk management platforms, big data portals, AI-powered services, financial models, and integration of fund information databases. Additional duties include managing data standards, establishing internal controls, designing IT architecture, fund disaster recovery, information security management, and supporting digital innovation technologies in fund management. The competency units include fund information planning, operation, analysis, infrastructure, and intelligence, enabling advanced digital transformation of NPS fund management operations. Required Skills & Knowledge Candidates must have knowledge of National Pension Fund regulations, capital markets (stocks, bonds, alternatives), financial products, financial practices, performance evaluation, risk management, and IT planning. Strong data analysis and management skills are essential, alongside knowledge of statistics, finance, taxation, accounting, AI, big data, software, hardware, and information security management. Required skills include office and statistical software, programming/data handling, financial/legal interpretation, and logical/systematic thinking in information security. Career Requirements Applicants must have either: Full-time Investment Manager (≥ 3 years investment experience, ≥ 1 month recruitment experience), or Responsible Investment Manager (≥ 7 years investment experience, ≥ 1 year recruitment experience). Preferred Qualifications Preferred certifications include CFA (Level 1–3), CPA (Korea/USA/Other countries), Attorney (Korea/USA/Other countries), Actuary, CIIA, FRM (domestic/international), CAIA, Tax Accountant, Investment Asset Management Specialist, Financial Investment Analyst, Fund Investment Advisor, and Asset Manager. IT-related certifications are also valued, including CISSP, CISM, CISA, PMP, Information Processing Engineer, Big Data Analysis Engineer, Information Security Engineer, and related IT qualifications."
