          "source_url": "https://www.swfi.com/v1/compass/6a4f585b60e31e972effd34b",
          "swfi_url": "https://www.swfi.com/v1/compass/6a4f585b60e31e972effd34b",
          "summary": "LINK : https://www.segalmarco.com/media/2561/bristol-county-global-multi-sector-fixed-income-rfp-2026.docx The Bristol County Retirement Board is seeking proposals from qualified investment management firms to manage a Global Multi-Sector Fixed Income mandate totaling approximately $32 million for the Bristol County Retirement System. The Board will evaluate proposals in accordance with Massachusetts General Laws Chapter 32 and all applicable investment guidelines administered by the Public Employees Retirement Administration Commission (PERAC). The Board reserves the right to select one or more investment managers and determine the allocation amount awarded to each selected firm based on its evaluation. Interested firms may submit questions regarding the Request for Proposal via email to Segal Marco Advisors. The Board also reserves the right to reject any or all proposals at its sole discretion if deemed to be in the best interests of the Retirement System."
