          "summary": "New York State Teachers Retirement System (NYSTRS) is expected to make between US$ 350 million to US$ 700 million of commercial real estate debt net investment for the next five years in order to reach a 6% allocation target for the asset class. NYSTRS disclosed in a meeting document most of its recent commercial real estate debt transactions have been focused on apartments and industrial assets. The investment plan will continue to evaluate lending opportunities in the property life sciences sector and other high-conviction property types consistent with the real estate equity program’s focus. The strategy for the NYSTRS' US$ 7.8 billion commercial real estate debt portfolio, includes core private debt, core public debt, and non-core private debt. The pension fund’s investment consultant Callan is also evaluating infrastructure debt opportunities to further diversify the pension fund’s portfolio."
