          "investors": "",
          "note": "",
          "summary": "Prudent Growth Partners, LLC, a private equity real estate investment firm based in Chapel Hill, North Carolina, has completed its $7.9 million acquisition of Comotara Center, a 55,650-square-foot neighborhood retail center located in Wichita, Kansas. The acquisition further expands the firm's portfolio of necessity-based retail properties in strategically located growth markets across the United States. Comotara Center is a Dollar Tree-anchored neighborhood retail center located within one of Wichita's premier shopping destinations. Originally constructed in 1985, with an expansion completed in 1987, the property is approximately 93% leased to 13 tenants featuring a diverse mix of restaurants, lifestyle retailers, and neighborhood service providers. In addition to Dollar Tree, the center is home to national and regional tenants including Five Guys, Edward Jones, State Farm, and other established businesses that serve the surrounding community. The property has been well maintained, with no significant deferred maintenance, providing a strong foundation for long-term ownership.",
