          "summary": "Truelink Capital (\"Truelink\"), a Los Angeles-based private equity firm focused on growth and long-term value creation, announced that it has entered into a definitive agreement to acquire JT Thorpe Group, Inc. (\"JT Thorpe\" or the \"Company\"), a leading provider of mission-critical specialty industrial maintenance and thermal management services supporting infrastructure and industrial end markets across North America. JT Thorpe's management team, led by CEO Kevin Howard, will continue to lead the business and will retain a significant ownership stake in the Company. The transaction is expected to close by the end of Q3, subject to the satisfaction of customary closing conditions. Financial terms of the transaction were not disclosed.",
