          "summary": "Brennan Investment Group (\"Brennan\"), a leading private real estate investment firm specializing in the acquisition, development, and management of industrial facilities across the United States, announced that it has closed on the acquisition of a 140,000-square-foot industrial facility located in Dayton, Ohio. Strategically located within the Springboro South industrial submarket, the property sits just minutes from the I-75 and Austin Landing interchange, one of the fastest-growing industrial and commercial corridors serving both Dayton and Greater Cincinnati. The property benefits from exceptional regional connectivity and access to a strong labor pool, making it well-positioned for long-term industrial occupancy.",
