          "note": "",
          "summary": "TSG Consumer (“TSG”), a leading private equity firm specializing in consumer brands, announced it has signed a definitive agreement to acquire a majority stake in Saltair, the award-winning body care brand founded by entrepreneur and model Iskra Lawrence. Following the close of the transaction, Iskra will additionally serve as Chief Community Advocate, deepening her focus on the brand’s community and consumer connection. Founded in 2022, Saltair is built on the foundation that “every body is welcome here,” pairing clinically supported, treatment-forward skincare actives with elevated, transportive fragrances at accessible price points, designed for every shape, skin tone, gender, age, and background. The brand is sold across retail and e-commerce. Raymond James served as the exclusive financial advisor to Saltair and Mintz, Levin, Cohn, Ferris, Glovsky, and Popeo P.C. and Polsinelli P.C. served as legal counsel. Ropes & Gray LLP provided legal counsel to TSG. Financial terms of the transaction were not disclosed. The transaction is subject to customary closing conditions and regulatory approval.",
