          "note": "",
          "summary": "Intercontinental Exchange, Inc. (NYSE: ICE), one of the world’s leading providers of financial market technology and data powering global capital markets, announced a definitive agreement to acquire MarketAxess Holdings Inc. (Nasdaq: MKTX), a preeminent electronic trading platform for global institutional fixed income markets. The combination will bring together two highly complementary businesses to form a more complete and connected fixed income platform. MarketAxess connects approximately 2,100 institutional investors and broker-dealers across more than 90 countries, enabling electronic trading in corporate bonds, municipal bonds, emerging market debt, Eurobonds, U.S. Treasuries, and other fixed income instruments. Together with ICE’s established retail and wealth focused bond trading franchise, deep data and analytics capabilities, and global index business, the combined platform will serve every segment of the fixed income market through a single, unified ecosystem. Under the terms of the agreement, ICE will acquire all outstanding shares of MarketAxess for $167 per share in cash, representing a 33% premium to MarketAxess’s closing price as of July 29, 2026, representing an equity value of approximately $6.0 billion and a total enterprise value of approximately $5.7 billion. The transaction has been unanimously approved by the Boards of Directors of both companies. BofA Securities is serving as financial advisor to Intercontinental Exchange, and Sullivan & Cromwell LLP and Morgan, Lewis and Bockius LLP are serving as legal advisors to Intercontinental Exchange. J.P. Morgan Securities LLC is serving as financial advisor to MarketAxess and Weil, Gotshal & Manges LLP is serving as legal advisor to MarketAxess.",
