          "native_amount_display": "$550,000,000",
          "investment_type": "Convertible",
          "investors": "G2 Venture Partners, Eclipse, Ribbit Capital, Salesforce Ventures, Activate Capital, John Doerr, Westly Group, StepStone Group, Liberty Mutual Strategic Ventures, Decarbonization Partners, Impact Science Ventures, Trust Ventures, Breakthrough Energy Ventures, and Lowercarbon Capital.",
          "note": "SWFI estimated equal contribution.",
          "summary": "Antora Energy, a leading U.S. energy storage company, announced its closing on $550 million in Series C funding. The oversubscribed round was co-led by G2 Venture Partners and Eclipse, with participation from new investors including Ribbit Capital, Salesforce Ventures, Activate Capital, John Doerr, Westly Group, StepStone Group, and Liberty Mutual Strategic Ventures. Existing investors also contributed to the round, including Decarbonization Partners, Impact Science Ventures, Trust Ventures, Breakthrough Energy Ventures, and Lowercarbon Capital. The Series C advances the company’s work to deliver affordable, reliable energy at the scale and speed that American industry and data centers require. The round will accelerate the deployment of large-scale projects across the country, enable Antora to expand production and establish a second U.S. manufacturing hub, and further strengthen the company’s domestic supply chain. The announcement comes on the heels of the company’s deployment of one of the largest battery storage projects in the world, a 5 gigawatt-hour system in South Dakota that advanced from initial construction to delivering energy in under 12 months. Antora is now scaling that proven approach, with a growing pipeline of signed agreements with hyperscalers and industrial leaders.",
          "source_url": "https://www.swfi.com/v1/transactions/6a6b8b38061383a01b7fc057",
          "swfi_url": "https://www.swfi.com/v1/transactions/6a6b8b38061383a01b7fc057"
