          "native_amount_display": "$10,000,000",
          "investment_type": "Convertible",
          "investors": "First Round Capital, 645 Ventures, Harlem Capital, Khosla Ventures, Slow Ventures, Wilshire Lane, Westbound, Collide Capital, Gallery Ventures, Ariel Alternatives CEO Mellody Hobson, Thrive Capital Founder Josh Kushner, Mercury Founder and CEO Immad Akhund, among others.",
          "note": "SWFI estimated equal contribution.",
          "summary": "Ellis, the first-of-its-kind AI-native operations platform for private credit, launched with more than $10 million in seed funding closed. First Round Capital led the financing with participation from a group of prominent operators and investors, including 645 Ventures, Harlem Capital, Khosla Ventures, Slow Ventures, Wilshire Lane, Westbound, Collide Capital, Gallery Ventures, Ariel Alternatives CEO Mellody Hobson, Thrive Capital Founder Josh Kushner, Mercury Founder and CEO Immad Akhund, among others. Private credit has become a multi-trillion dollar market and increasingly a vital source of capital for businesses around the world, yet the operating infrastructure behind the market has not kept pace. Many private credit managers still run critical workflows across disconnected fund-administrator outputs, general ledgers, loan-servicing systems, bank data, legal documents and spreadsheets. Teams spend significant time reconciling different versions of the same number, slowing closes and reporting, increasing operational risk and making it harder to scale efficiently.",
          "source_url": "https://www.swfi.com/v1/transactions/6a6b8802df6d6ceb3b1fde52",
          "swfi_url": "https://www.swfi.com/v1/transactions/6a6b8802df6d6ceb3b1fde52"
