          "investors": "Trust for London, Resolution Ventures, Ufi Ventures, Second Century Ventures (as part of the REACH UK programme), angel investors from Daring Capital.",
          "note": "SWFI estimated equal contribution.",
          "summary": "TaskHer, a London, UK-based provider of a platform connecting customers with verified, skilled tradeswomen, raised £650K in funding. The round was co-led by Trust for London, Resolution Ventures, Ufi Ventures, and Second Century Ventures (as part of the REACH UK programme), with participation from angel investors from Daring Capital. The company intends to use the funds to support the next phase of its growth, including expansion into B2B partnerships with housing associations, women’s refuges, and lettings agencies, and accelerate its platform development. Founded in 2022 by Anna Moynihan and Paul Moynihan, TaskHer provides a platform that connects homeowners and organisations with verified tradeswomen, improving home services hiring while tackling the UK’s trades industry skills shortage. The solution enables customers to find and hire female tradespeople for property maintenance and home services.",
