          "investors": "Guozhong Capital, IDG Capital, China Everbright Limited, Jolmo Capital, Win-Win Capital, SND Financial Holdings, and Longmen Capital.",
          "note": "SWFI estimated equal contribution.",
          "summary": "Ractigen Therapeutics, a Shanghai, China-based clinical-stage biotechnology company developing small activating RNA (saRNA) therapeutics and extrahepatic delivery systems, raised over $31M in funding. The round was led by Guozhong Capital with participation from IDG Capital, China Everbright Limited, Jolmo Capital, Win-Win Capital, SND Financial Holdings, and Longmen Capital. The company intends to use the funds to accelerate the clinical development of its saRNA assets, including advancing Phase 2 clinical trials for RAG-01 in non-muscle-invasive bladder cancer (NMIBC), preparing IND filing for RAG-18 in Duchenne muscular dystrophy (DMD), advancing Phase 2 clinical trials for RAG-17 in amyotrophic lateral sclerosis (ALS), and expanding its proprietary extrahepatic delivery platforms (SCAD and LiCO). Led by CEO Dr. Long-Cheng Li, Ractigen Therapeutics is a biopharmaceutical company developing new RNA therapeutics through its clinically validated RNA activation (RNAa) technology. Their platform uses saRNAs targeting gene promoter regions to upregulate endogenous protein expression at the transcriptional level, alongside proprietary carrier-free delivery platforms (SCAD for CNS delivery and LiCO for systemic multi-tissue delivery) designed to unlock therapeutic targets outside the liver.",
          "source_url": "https://www.swfi.com/v1/transactions/6a6b7571e4146d89e9a2f10b",
          "swfi_url": "https://www.swfi.com/v1/transactions/6a6b7571e4146d89e9a2f10b"
