          "note": "SWFI estimated equal contribution.",
          "summary": "DataBahn, a Dallas, Texas-based provider of an agentic data control plane platform, raised $40M in Series B financing. The round was led by Insight Partners with participation from Forgepoint, GTM Capital and S3 Ventures. The raise brought the total amount to $59M. The company intends to use the funds to accelerate investments in R&D and product innovation, expanding its agentic data control plane to serve organizations of every size, from large global enterprises to mid-market businesses. Led by CEO Nanda Santhana, DataBahn provides an agentic data control plane designed to ingest, normalize, enrich, govern, orchestrate, and route telemetry enterprise data for both applications and AI systems. Their platform ingests, normalizes, enriches, governs, and routes telemetry from 600+ sources with complete data and AI neutrality across any source, destination, or model without vendor lock-in.",
