          "note": "SWFI estimated equal contribution.",
          "summary": "K2 Space, a Torrance, CA-based company manufacturing satellites, raised $500M in Series D funding, at a $6.8B valuation. The round was led by Kleiner Perkins and ICONIQ with participation from CapitalG, Lightspeed, Altimeter, Spark Capital, Sands Capital, ARK Invest, T. Rowe Price Associates, Inc., and other existing investors. The raise brought the total amount to over $1 Billion. The company intends to use the funds to accelerate expand operations and its development efforts. Led by CEO Karan Kunjur and CTO Neel Kunjur, K2 Space is a manufacturer of satellites for commercial, scientific, and defense missions. Their platform provides satellite buses designed to optimize performance in power, propulsion, and payload capacity.",
