          "investors": "Base10 Partners and Y Combinator’s Winter 2026 batch.",
          "note": "SWFI estimated equal contribution.",
          "summary": "Vector Legal, a San Francisco, CA-based AI-native law firm and legal technology platform for startups, closed a $5.19m seed financing. The round was led by Base10 Partners, shortly after completing Y Combinator’s Winter 2026 batch. The company intends to use the funds to expand operations and its platform development efforts. Founded in 2026 by Mitch Duncombe and Keenan Venuti, Vector Legal is an AI-native law firm which is launching a hybrid product/service offering for Startups, which will include company formations, commercial contracts and trademarks. Vector Legal, P.C. recently represented Corgi Insurance on its $160m round and has closed numerous client financings in recent months. Duncombe is a senior transactional attorney who previously served as a Startup and M&A associate at a leading Silicon Valley firm and as legal counsel at Y Combinator. Venuti previously served as a Staff AI Software Engineer at Ironclad, the enterprise contract management platform backed by Sequoia and Accel.",
