          "note": "SWFI estimated equal contribution.",
          "summary": "Lydian, a Boston, MA-based provider of synthetic aviation fuel production solutions, raised $43M in Series A funding. The round was led by Breakthrough Energy Ventures with participation from AP Ventures, Builders Vision, Congruent Ventures, Galvanize, Grok Ventures, Overture, Union Square Ventures, and Voyager Ventures. The company intends to use the funds to support the launch and scaling of PIVOT, its full-stack synthetic fuel production platform. Led by CEO Joe Rodden, Lydian is a technology company developing a synthetic aviation fuel. Their platform, PIVOT, converts captured carbon dioxide and hydrogen into ASTM-approved, drop-in sustainable aviation fuel using proprietary reactor technologies, catalysts, software, and standardized, factory-built modules designed to reduce capital costs and operational complexity.",
