          "investors": "General Atlantic and FirstMark.",
          "note": "SWFI estimated equal contribution.",
          "summary": "Gravie, a Minneapolis, MN-based provider of health benefits solutions, raised an undisclosed amount in new funding. The round was led by General Atlantic with participation from FirstMark. The raise brought the total amount to $463M. The company intends to use the funds to support its ongoing expansion, product development, and go-to-market efforts. Led by CEO Steve Wolin, Gravie is a health benefits company developing a platform that offers both level-funded group health plans and Individual Coverage Health Reimbursement Arrangements (ICHRA), giving employers the flexibility to choose the right benefits model for their workforce and partnering with brokers and employers of all sizes nationwide.",
