          "investors": "Greenoaks, Index Ventures, Hanabi, Bain Capital Ventures, A*, Factory, and CVS Health Ventures, and new participation from Definition.",
          "note": "SWFI estimated equal contribution.",
          "summary": "Simile, a San Francisco, California-based developer of AI-powered human behavior foundation models and predictive simulation software, raised $200m in Series B funding at a $2 billion valuation. The round was led by Greenoaks, with participation from returning investor Index Ventures, alongside follow-on backing from Hanabi, Bain Capital Ventures, A*, Factory, and CVS Health Ventures, and new participation from Definition. The company intends to use the capital to accelerate the technical training of its core human behavior foundation models, expand its simulation compute layers, and scale its commercial engineering operations across enterprise healthcare, financial services, and media markets. Led by Founder and CEO Joon Sung Park, Simile develops a specialized physical and behavioral simulation platform engineered to replicate complex human society interactions, allowing corporate enterprises to accurately test decisions before real-world deployment.",
