          "note": "SWFI estimated equal contribution.",
          "summary": "Onyx Security, a NYC-based provider of a secure AI control plane platform for enterprises, raised $113M in Series B funding. The round was led by Bessemer Venture Partners with participation from Cyberstarts, TCV, Conviction, FirstMark, Vintage, QuantumLight, and G Squared. The raise brought the total amount to $153M. The company intends to use the funds for training the next generation of its proprietary models and for scaling the enterprise go-to-market in the United States and beyond. Led by CEO Maxim Bar Kogan, Onyx Security is an AI control company developing a platform that enables security, governance, and infrastructure teams and enterprises to use a unified control over AI agents to discover, monitor, and control how AI works in their environment ensuring safe operation and compliance.",
