          "investors": "Vista Equity Partners, AllianceBernstein, Blue Owl Capital, Carlyle, Fortress Investment Group, Golub Capital, Lord Abbett, and Royal Bank of Canada (RBC).",
          "note": "SWFI estimated equal contribution.",
          "summary": "CAIS, a NYC-based provider of an alternative investment platform for independent financial advisors, raised $170M in Series D funding, at $2 Billion valuation. The round was led by Vista Equity Partners with participation from AllianceBernstein, Blue Owl Capital, Carlyle, Fortress Investment Group, Golub Capital, Lord Abbett, and Royal Bank of Canada (RBC). The raise brought the total amount to nearly $600M. The company intends to use the funds to expand its platform, scale its technology and AI capabilities, explore strategic opportunities, and continue delivering innovation for advisors. Led by Founder and CEO Matt Brown, CAIS is a provider of an alternative investment platform for independent financial advisors. Their solution empowers the pre-trade, trade, and post-trade lifecycle of alternative investments, offering financial advisors and alternative asset managers a single operating system to access, evaluate, and manage alternative investments.",
