          "note": "SWFI estimated equal contribution.",
          "summary": "CopySight, a Los Angeles, CA-based provider of an AI IP governance platform for commercial content creation, raised $3M in Seed funding. The round was led by Mucker Capital with participation from Taisu VC, Flint Capital, and Yellow Rocks!. The company intends to use the funds to scale its proprietary scoring architecture deeper into enterprise video production pipelines. Led by CEO Artem Petrov and CTO Konstantin Orlov, CopySight is an AI IP governance company that helps studios, platforms, and enterprises evaluate and manage copyright risk in AI-generated content. Their solution, CopyScore V2, analyzes images and video frame by frame to evaluate risks across trademarks, characters, brand designs, celebrity likenesses, and art styles, generating an immutable chain-of-creation log for compliance.",
